//! Deterministic synthetic benchmark corpus (`--generate-corpus`).
//!
//! Every image is a pure function of (seed, class, x, y) evaluated in integer
//! math, so equal options always produce byte-identical files.

mod encode;

use std::path::Path;

use anyhow::{Context, Result};
use clap::ValueEnum;
use serde_json::{Value, json};

pub const GENERATOR: &str = "smart-compress-benchmark --generate-corpus";
/// Bump whenever any generated byte can change.
pub const GENERATOR_VERSION: u32 = 1;
pub const DEFAULT_SEED: u64 = 0x5EED_C0DE_2026;
pub const MANIFEST_NAME: &str = "corpus.json";

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum SizeClass {
    Tiny,
    #[value(name = "512")]
    Px512,
    #[value(name = "2048")]
    Px2048,
    #[value(name = "12mp")]
    Mp12,
    #[value(name = "50mp")]
    Mp50,
    #[value(name = "199mp")]
    Mp199,
}

impl SizeClass {
    pub const DEFAULT: [Self; 3] = [Self::Tiny, Self::Px512, Self::Px2048];

    fn name(self) -> &'static str {
        match self {
            Self::Tiny => "tiny",
            Self::Px512 => "512",
            Self::Px2048 => "2048",
            Self::Mp12 => "12mp",
            Self::Mp50 => "50mp",
            Self::Mp199 => "199mp",
        }
    }

    /// The megapixel classes are only written for classes marked `large`.
    fn is_large(self) -> bool {
        matches!(self, Self::Mp12 | Self::Mp50 | Self::Mp199)
    }

    fn dimensions(self, class_index: usize) -> (u32, u32) {
        const TINY: [u32; 5] = [16, 24, 32, 48, 64];
        match self {
            Self::Tiny => (TINY[class_index % 5], TINY[(class_index + 2) % 5]),
            Self::Px512 => (512, 512),
            Self::Px2048 => (2048, 2048),
            Self::Mp12 => (4000, 3000),
            Self::Mp50 => (8160, 6120),
            Self::Mp199 => (16320, 12240),
        }
    }
}

struct Canvas {
    seed: u64,
    width: u32,
    height: u32,
}

enum Kind {
    Png,
    PngAlpha,
    PngIcc(&'static str, [[i32; 3]; 3]),
    Jpeg,
    JpegExif(u16),
    JpegCmyk,
}

struct Class {
    name: &'static str,
    kind: Kind,
    large: bool,
    description: &'static str,
    pixel: fn(&Canvas, u32, u32) -> [u8; 4],
}

