fn icc_description(name: &str) -> String {
    format!("smart-compress synthetic {name}")
}

/// Writes the corpus and its manifest into `dir` and returns the manifest.
pub fn generate(dir: &Path, sizes: &[SizeClass], seed: u64) -> Result<Value> {
    std::fs::create_dir_all(dir)
        .with_context(|| format!("creating corpus directory {}", dir.display()))?;
    let provenance = json!({
        "generator": GENERATOR,
        "generator_version": GENERATOR_VERSION,
        "seed": seed,
    });
    let mut files = Vec::new();
    // Canonical order, so repeated or reordered --corpus-sizes values do not matter.
    for size in SizeClass::value_variants()
        .iter()
        .filter(|size| sizes.contains(size))
    {
        for (index, class) in CLASSES.iter().enumerate() {
            if size.is_large() && !class.large {
                continue;
            }
            let (width, height) = match (&class.kind, size) {
                (Kind::JpegExif(_), SizeClass::Tiny) => (64, 48),
                (Kind::JpegExif(_), _) => {
                    let (width, height) = size.dimensions(index);
                    (width, height * 3 / 4)
                }
                _ => size.dimensions(index),
            };
            let canvas = Canvas {
                seed: mix(seed ^ mix(index as u64)),
                width,
                height,
            };
            let pixel = |x, y| (class.pixel)(&canvas, x, y);
            let (format, extension, bytes) = match class.kind {
                Kind::Png => ("png", "png", encode::png(width, height, false, None, pixel)),
                Kind::PngAlpha => ("png", "png", encode::png(width, height, true, None, pixel)),
                Kind::PngIcc(name, colorants) => {
                    let profile = encode::icc_profile(&icc_description(name), colorants);
                    let icc = Some((name, profile.as_slice()));
                    ("png", "png", encode::png(width, height, false, icc, pixel))
                }
                Kind::Jpeg => (
                    "jpeg",
                    "jpg",
                    encode::jpeg(width, height, false, None, pixel),
                ),
                Kind::JpegExif(orientation) => {
                    let exif = encode::exif_orientation(orientation);
                    let bytes = encode::jpeg(width, height, false, Some(&exif), pixel);
                    ("jpeg", "jpg", bytes)
                }
                Kind::JpegCmyk => (
                    "jpeg",
                    "jpg",
                    encode::jpeg(width, height, true, None, pixel),
                ),
            };
            let name = format!("{}-{}.{extension}", class.name, size.name());
            let path = dir.join(&name);
            std::fs::write(&path, &bytes)
                .with_context(|| format!("writing corpus file {}", path.display()))?;
            files.push(json!({
                "path": name,
                "content_class": class.name,
                "size_class": size.name(),
                "width": width,
                "height": height,
                "format": format,
                "bytes": bytes.len(),
                "blake3": blake3::hash(&bytes).to_hex().to_string(),
                "synthetic": true,
                "description": class.description,
                "provenance": provenance,
            }));
        }
    }

    let manifest = json!({
        "schema_version": 1,
        "corpus": "smart-compress-synthetic-corpus",
        "note": "Every file is procedurally generated; none is a real photograph or screenshot.",
        "provenance": provenance,
        "files": files,
    });
    let mut text =
        serde_json::to_string_pretty(&manifest).context("serializing corpus manifest")?;
    text.push('\n');
    let path = dir.join(MANIFEST_NAME);
    std::fs::write(&path, text)
        .with_context(|| format!("writing corpus manifest {}", path.display()))?;
    Ok(manifest)
}

/// splitmix64 finalizer.
fn mix(value: u64) -> u64 {
    let mut z = value.wrapping_add(0x9E37_79B9_7F4A_7C15);
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

fn hash(seed: u64, x: u32, y: u32) -> u64 {
    mix(seed ^ mix(u64::from(x) << 32 | u64::from(y)))
}

/// Smoothstep-interpolated lattice noise in 0..=65280 (8.8 fixed point).
fn value_noise(seed: u64, x: u32, y: u32, cell: u32) -> u32 {
    let (cell_x, cell_y) = (x / cell, y / cell);
    let smooth = |position: u32| {
        let t = position % cell * 256 / cell;
        (t * t * (768 - 2 * t)) >> 16
    };
    let (weight_x, weight_y) = (smooth(x), smooth(y));
    let corner = |dx, dy| (hash(seed, cell_x + dx, cell_y + dy) & 0xFF) as u32;
    let top = corner(0, 0) * (256 - weight_x) + corner(1, 0) * weight_x;
    let bottom = corner(0, 1) * (256 - weight_x) + corner(1, 1) * weight_x;
    (top * (256 - weight_y) + bottom * weight_y) >> 8
}

/// Sum of `octaves` noise layers with halving cell size and amplitude, in 0..=255.
fn fractal_noise(seed: u64, x: u32, y: u32, cell: u32, octaves: u32) -> i32 {
    let (mut total, mut ceiling) = (0, 0);
    for octave in 0..octaves {
        total += value_noise(
            seed.wrapping_add(u64::from(octave)),
            x,
            y,
            (cell >> octave).max(1),
        ) >> octave;
        ceiling += 65280 >> octave;
    }
    (total * 255 / ceiling) as i32
}

fn rgb(r: i32, g: i32, b: i32) -> [u8; 4] {
    let channel = |value: i32| value.clamp(0, 255) as u8;
    [channel(r), channel(g), channel(b), 255]
}

/// 3x5 glyphs for A-Z then 0-9; each octal digit is one row, top row first.
const FONT: [u16; 36] = [
    0o25755, 0o65656, 0o34443, 0o65556, 0o74647, 0o74644, 0o34553, 0o55755, 0o72227, 0o11152,
    0o55655, 0o44447, 0o57755, 0o65555, 0o25552, 0o65644, 0o25563, 0o65655, 0o34216, 0o72222,
    0o55557, 0o55552, 0o55775, 0o55255, 0o55222, 0o71247, 0o75557, 0o26227, 0o61247, 0o61216,
    0o55711, 0o74616, 0o34757, 0o71222, 0o75757, 0o75716,
];

/// Whether (x, y) is inked by a grid of pseudo-random glyphs and spaces.
fn text_ink(seed: u64, x: u32, y: u32, scale: u32) -> bool {
    let (cell_width, cell_height) = (4 * scale, 7 * scale);
    let (glyph_x, glyph_y) = (x % cell_width / scale, y % cell_height / scale);
    if glyph_x >= 3 || glyph_y >= 5 {
        return false;
    }
    // Picks past the end of the font are spaces.
    let pick = hash(seed, x / cell_width, y / cell_height) % 44;
    FONT.get(pick as usize)
        .is_some_and(|glyph| glyph >> (14 - (glyph_y * 3 + glyph_x)) & 1 == 1)
}

fn photo(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let cell = (canvas.width.max(canvas.height) / 3).max(2);
    let luma = fractal_noise(canvas.seed, x, y, cell, 8);
    let warmth = fractal_noise(canvas.seed ^ 1, x, y, cell, 3) - 128;
    let sky = (255 * (canvas.height - y) / canvas.height) as i32;
    let base = (luma * 3 + sky) / 4 + (hash(canvas.seed ^ 2, x, y) & 7) as i32 - 4;
    rgb(base + warmth / 2, base, base - warmth / 2 + sky / 8)
}

fn oriented_photo(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    if x < canvas.width / 4 && y < canvas.height / 4 {
        return rgb(220, 0, 0);
    }
    photo(canvas, x, y)
}

fn screenshot(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let ink = text_ink(canvas.seed, x, y, (1 + canvas.width / 1024).min(3));
    let pick = |pen, paper| if ink { pen } else { paper };
    if y < canvas.height / 12 {
        return pick(rgb(235, 238, 245), rgb(32, 44, 68));
    }
    if x < canvas.width / 5 {
        return pick(rgb(70, 76, 90), rgb(236, 238, 242));
    }
    let (card_width, card_height) = ((canvas.width / 4).max(8), (canvas.height / 5).max(8));
    if x.is_multiple_of(card_width) || y.is_multiple_of(card_height) {
        return rgb(208, 212, 220);
    }
    match hash(canvas.seed ^ 3, x / card_width, y / card_height) % 6 {
        0 => pick(rgb(255, 255, 255), rgb(36, 112, 220)),
        1 => pick(rgb(20, 120, 60), rgb(250, 250, 250)),
        _ => pick(rgb(40, 40, 48), rgb(255, 255, 255)),
    }
}

fn ui_text(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let scale = (2 + canvas.width / 512).min(6);
    let (pen, paper) = match y / (7 * scale) % 8 {
        0 => (rgb(244, 244, 246), rgb(28, 30, 36)),
        5 => (rgb(120, 60, 0), rgb(255, 244, 200)),
        _ => (rgb(24, 26, 32), rgb(246, 247, 249)),
    };
    if text_ink(canvas.seed, x, y, scale) {
        pen
    } else {
        paper
    }
}

fn small_text(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let ink = text_ink(canvas.seed, x, y, 1);
    match (x < canvas.width / 2, ink) {
        (true, true) => rgb(0, 0, 0),
        (true, false) | (false, true) => rgb(255, 255, 255),
        (false, false) => rgb(0, 60, 200),
    }
}

/// Coordinates relative to the canvas center, doubled to stay integral.
fn centered(canvas: &Canvas, x: u32, y: u32) -> (i64, i64, i64) {
    (
        2 * i64::from(x) + 1 - i64::from(canvas.width),
        2 * i64::from(y) + 1 - i64::from(canvas.height),
        i64::from(canvas.width.min(canvas.height)),
    )
}

fn flat_icon(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let (dx, dy, size) = centered(canvas, x, y);
    let within = |radius: i64| dx * dx + dy * dy <= radius * radius;
    if dx.abs().max(dy.abs()) > size * 7 / 8 {
        rgb(240, 240, 240)
    } else if within(size * 5 / 8) && !within(size * 3 / 8) {
        rgb(255, 255, 255)
    } else if dx.abs() < size / 8 && dy.abs() < size / 4 {
        rgb(255, 196, 0)
    } else {
        rgb(36, 112, 220)
    }
}

fn gradient(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let ramp = |value: u32, length: u32| (255 * value / (length - 1).max(1)) as i32;
    rgb(
        ramp(x, canvas.width),
        ramp(y, canvas.height),
        ramp(x + y, canvas.width + canvas.height - 1),
    )
}

fn noise(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let value = hash(canvas.seed, x, y);
    [value as u8, (value >> 8) as u8, (value >> 16) as u8, 255]
}

fn transparency(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let (dx, dy, size) = centered(canvas, x, y);
    let distance = ((dx * dx + dy * dy) as u64).isqrt() as i64;
    // Opaque inside radius 0.30, transparent outside 0.45, linear in between.
    let (inner, outer) = (size * 6 / 10, size * 9 / 10);
    let alpha = ((outer - distance) * 255 / (outer - inner)).clamp(0, 255) as u8;
    let [r, g, b, _] = gradient(canvas, x, y);
    [r, g, b, alpha]
}

fn alpha_fringe(_canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    match (x + 2 * y) % 24 {
        0..=7 => [200, 30, 90, 255],
        8 | 23 => [255, 255, 255, 128],
        9 | 22 => [0, 0, 0, 48],
        _ => [0, 255, 0, 0],
    }
}

fn checkerboard(_canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let value = if (x + y).is_multiple_of(2) { 0 } else { 255 };
    rgb(value, value, value)
}

fn one_pixel_lines(_canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    if x.is_multiple_of(8) {
        rgb(0, 0, 0)
    } else if y % 8 == 4 {
        rgb(220, 0, 0)
    } else if (x + y) % 16 == 7 {
        rgb(0, 0, 220)
    } else {
        rgb(255, 255, 255)
    }
}

fn color_bars(canvas: &Canvas, x: u32, y: u32) -> [u8; 4] {
    let half = canvas.height / 2;
    if y < half {
        let bar = 8 * x / canvas.width;
        let on = |bit: u32| if bar & bit != 0 { 255 } else { 0 };
        return rgb(on(4), on(2), on(1));
    }
    let ramp = (255 * x / (canvas.width - 1).max(1)) as i32;
    match 6 * (y - half) / (canvas.height - half) {
        0 => rgb(ramp, 0, 0),
        1 => rgb(0, ramp, 0),
        2 => rgb(0, 0, ramp),
        3 => rgb(ramp, ramp, 0),
        4 => rgb(0, ramp, ramp),
        _ => rgb(ramp, ramp, ramp),
    }
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use smart_compress_core::image_probe::{
        DecodedSource, ImageDecodeLimits, decode_source_with_limits,
    };

    use super::*;

    /// Process-unique scratch directory, removed on drop.
    struct Scratch(PathBuf);

    impl Scratch {
        fn new(name: &str) -> Self {
            let path = std::env::temp_dir().join(format!(
                "smart-compress-corpus-test-{}-{name}",
                std::process::id()
            ));
            std::fs::create_dir_all(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for Scratch {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    /// Decodes with the image crate through the product's own entry point.
    fn decode(path: &Path) -> DecodedSource {
        decode_source_with_limits(path, ImageDecodeLimits::default())
            .unwrap_or_else(|error| panic!("{} did not decode: {error:#}", path.display()))
    }

    fn max_channel_error(decoded: &[u8], expected: impl Iterator<Item = u8>) -> u8 {
        decoded
            .iter()
            .zip(expected)
            .map(|(&actual, wanted)| actual.abs_diff(wanted))
            .max()
            .unwrap()
    }

    #[test]
    fn corpus_is_deterministic_and_decodes_at_stated_dimensions() {
        // The 2048 class runs the same code on more pixels and only slows the test.
        const SIZES: [SizeClass; 2] = [SizeClass::Tiny, SizeClass::Px512];
        let (first, second) = (Scratch::new("first"), Scratch::new("second"));
        let manifest = generate(&first.0, &SIZES, DEFAULT_SEED).unwrap();
        let repeat = generate(&second.0, &SIZES, DEFAULT_SEED).unwrap();
        assert_eq!(manifest, repeat);
        assert_eq!(
            std::fs::read(first.0.join(MANIFEST_NAME)).unwrap(),
            std::fs::read(second.0.join(MANIFEST_NAME)).unwrap()
        );

        let files = manifest["files"].as_array().unwrap();
        assert_eq!(files.len(), CLASSES.len() * SIZES.len());
        for file in files {
            let name = file["path"].as_str().unwrap();
            let bytes = std::fs::read(first.0.join(name)).unwrap();
            assert_eq!(bytes, std::fs::read(second.0.join(name)).unwrap(), "{name}");
            assert_eq!(file["bytes"], bytes.len(), "{name}");
            assert_eq!(
                file["blake3"],
                blake3::hash(&bytes).to_hex().to_string(),
                "{name}"
            );

            let decoded = decode(&first.0.join(name));
            assert_eq!(file["width"], decoded.image.width(), "{name}");
            assert_eq!(file["height"], decoded.image.height(), "{name}");
            let expected_format = if file["format"] == "png" {
                "Png"
            } else {
                "Jpeg"
            };
            assert_eq!(
                decoded.metadata.format.as_deref(),
                Some(expected_format),
                "{name}"
            );

            let class = file["content_class"].as_str().unwrap();
            assert_eq!(
                decoded.image.color().has_alpha(),
                matches!(class, "transparency" | "alpha-fringe"),
                "{name}"
            );
            assert_eq!(
                decoded.metadata.orientation_applied(),
                class == "exif-orientation-6",
                "{name}"
            );
            let expected_icc = match class {
                "icc-srgb" => Some(encode::icc_profile(
                    &icc_description("sRGB"),
                    encode::SRGB_COLORANTS,
                )),
                "icc-display-p3" => Some(encode::icc_profile(
                    &icc_description("Display P3"),
                    encode::DISPLAY_P3_COLORANTS,
                )),
                _ => None,
            };
            assert_eq!(decoded.metadata.icc_profile, expected_icc, "{name}");
        }
    }

    #[test]
    fn seed_changes_the_generated_bytes() {
        let (first, second) = (Scratch::new("seed-a"), Scratch::new("seed-b"));
        let default = generate(&first.0, &[SizeClass::Tiny], DEFAULT_SEED).unwrap();
        let other = generate(&second.0, &[SizeClass::Tiny], DEFAULT_SEED + 1).unwrap();
        assert_ne!(default["files"][0]["blake3"], other["files"][0]["blake3"]);
    }

    #[test]
    fn png_writer_round_trips_exact_pixels() {
        let scratch = Scratch::new("png");
        // Flat runs, a short period and noise exercise matches and literals.
        let canvas = Canvas {
            seed: 7,
            width: 67,
            height: 41,
        };
        let pixel = |x: u32, y: u32| match y / 14 {
            0 => [9, 9, 9, 200],
            1 => alpha_fringe(&canvas, x, y),
            _ => noise(&canvas, x, y),
        };
        let path = scratch.0.join("round-trip.png");
        std::fs::write(&path, encode::png(67, 41, true, None, pixel)).unwrap();

        let expected: Vec<u8> = (0..41)
            .flat_map(|y| (0..67).flat_map(move |x| pixel(x, y)))
            .collect();
        assert_eq!(decode(&path).image.as_bytes(), expected);
    }

    #[test]
    fn jpeg_writers_decode_close_to_the_source_pixels() {
        let scratch = Scratch::new("jpeg");
        // Deliberately not a multiple of eight in either direction.
        let canvas = Canvas {
            seed: 0,
            width: 45,
            height: 27,
        };
        let pixel = |x: u32, y: u32| gradient(&canvas, x, y);
        let expected = || {
            (0..27)
                .flat_map(|y| (0..45).flat_map(move |x| pixel(x, y)))
                .enumerate()
                .filter(|(index, _)| index % 4 != 3)
                .map(|(_, value)| value)
        };
        for (name, cmyk) in [("ycbcr.jpg", false), ("cmyk.jpg", true)] {
            let path = scratch.0.join(name);
            std::fs::write(&path, encode::jpeg(45, 27, cmyk, None, pixel)).unwrap();
            let decoded = decode(&path).image.to_rgb8();
            assert_eq!((decoded.width(), decoded.height()), (45, 27), "{name}");
            let error = max_channel_error(decoded.as_raw(), expected());
            assert!(error <= 12, "{name} is off by up to {error} levels");
        }
    }

    #[test]
    fn icc_profile_is_structurally_valid() {
        let profile = encode::icc_profile("test", encode::DISPLAY_P3_COLORANTS);
        let word = |offset: usize| {
            u32::from_be_bytes(profile[offset..offset + 4].try_into().unwrap()) as usize
        };
        assert_eq!(word(0), profile.len());
        assert_eq!(profile.len() % 4, 0);
        assert_eq!(&profile[36..40], b"acsp");
        let tags = word(128);
        assert_eq!(tags, 9);
        for tag in 0..tags {
            let entry = 132 + 12 * tag;
            let (offset, size) = (word(entry + 4), word(entry + 8));
            assert_eq!(offset % 4, 0);
            assert!(offset >= 132 + 12 * tags && offset + size <= profile.len());
            let expected_type: &[u8] = match &profile[entry..entry + 4] {
                b"desc" => b"desc",
                b"cprt" => b"text",
                b"rTRC" | b"gTRC" | b"bTRC" => b"curv",
                _ => b"XYZ ",
            };
            assert_eq!(&profile[offset..offset + 4], expected_type);
        }
    }
}
